import 'dart:async';

import 'package:flexiphones/extensions/value_formating.dart';
import 'package:flexiphones/models/promo_usage_m.dart';
import 'package:flexiphones/provider/provider_class.dart';
import 'package:flexiphones/shared_widgets/generalwidgets.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';

/// Shows the partner's real promo code (generated by the backend at
/// registration) and who has used it (GET /partner/promo-usage, polled
/// every 15s while this tab is open). Copy-to-clipboard only — no
/// share/QR packages are in pubspec yet.
class AgentShare extends StatefulWidget {
  const AgentShare({super.key});

  @override
  State<AgentShare> createState() => _AgentShareState();
}

class _AgentShareState extends State<AgentShare> {
  Timer? _poll;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final p = Provider.of<SharedProvider>(context, listen: false);
      p.getPromoUsage();
      // The doc asks for 10s or slower on an open screen; stop on close.
      _poll = Timer.periodic(const Duration(seconds: 15), (_) async {
        if (!mounted) return;
        final fresh = await p.getPromoUsage(incremental: true);
        if (fresh > 0 && mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                fresh == 1
                    ? "Someone just used your promo code"
                    : "$fresh people just used your promo code",
              ),
            ),
          );
        }
      });
    });
  }

  @override
  void dispose() {
    _poll?.cancel();
    super.dispose();
  }

  void _copy(String text, String toast) {
    Clipboard.setData(ClipboardData(text: text));
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(toast)));
  }

  @override
  Widget build(BuildContext context) {
    var ch = Theme.of(context).colorScheme;
    final p = Provider.of<SharedProvider>(context);
    final code = p.agentPromoCode;
    final hasCode = code != null && code.isNotEmpty;
    final usage = p.promoUsage;

    return SafeArea(
      child: RefreshIndicator(
        onRefresh: () => p.getPromoUsage(),
        child: ListView(
          padding: const EdgeInsets.fromLTRB(20, 24, 20, 40),
          children: [
            Text(
              "Share your code",
              style: ptstyle(
                size: 26,
                weight: 700,
                color: ch.onSurface,
              ).copyWith(letterSpacing: -0.6),
            ),
            const SizedBox(height: 6),
            Text(
              "Customers who use your promo code are tied to your agent account.",
              style: ptstyle(size: 13, weight: 400, color: ch.onSurfaceVariant),
            ),
            const SizedBox(height: 20),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(vertical: 26),
              decoration: BoxDecoration(
                color: ch.primaryFixed.withOpacity(0.25),
                borderRadius: BorderRadius.circular(22),
              ),
              child: Column(
                children: [
                  Text(
                    "YOUR PROMO CODE",
                    style: ptstyle(
                      size: 10,
                      weight: 600,
                      color: ch.onSurfaceVariant,
                    ).copyWith(letterSpacing: 1.4),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    hasCode ? code : "Not available",
                    style: ptstyle(
                      size: hasCode ? 30 : 14,
                      weight: 800,
                      color: ch.primary,
                    ).copyWith(letterSpacing: hasCode ? 3 : 0),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 14),
            if (hasCode)
              Row(
                children: [
                  Expanded(
                    child: SizedBox(
                      height: 46,
                      child: FilledButton.icon(
                        onPressed: () => _copy(code, "Promo code copied"),
                        icon: const Icon(Icons.copy_rounded, size: 18),
                        label: Text(
                          "Copy code",
                          style: ptstyle(size: 13, weight: 600),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: SizedBox(
                      height: 46,
                      child: OutlinedButton.icon(
                        onPressed:
                            () => _copy(
                              "Get your next phone on flexible payments with FlexiPhones. Enter my promo code $code in the app under Profile → Promo Code.",
                              "Message copied",
                            ),
                        icon: const Icon(
                          Icons.chat_bubble_outline_rounded,
                          size: 18,
                        ),
                        label: Text(
                          "Invite text",
                          style: ptstyle(size: 13, weight: 600),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            const SizedBox(height: 28),
            Row(
              children: [
                Expanded(
                  child: Text(
                    "Who used my code",
                    style: ptstyle(size: 17, weight: 700, color: ch.onSurface),
                  ),
                ),
                if (usage != null)
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color: ch.primary.withOpacity(0.1),
                      borderRadius: BorderRadius.circular(100),
                    ),
                    child: Text(
                      "${usage.timesUsed} total",
                      style: ptstyle(size: 11, weight: 600, color: ch.primary),
                    ),
                  ),
              ],
            ),
            const SizedBox(height: 10),
            if (p.loadingPromoUsage && usage == null)
              const Padding(
                padding: EdgeInsets.all(24),
                child: Center(child: CircularProgressIndicator()),
              )
            else if (p.promoUsers.isEmpty)
              Container(
                padding: const EdgeInsets.all(20),
                decoration: BoxDecoration(
                  color: ch.surfaceContainerLow,
                  borderRadius: BorderRadius.circular(18),
                ),
                child: Text(
                  "No one has used your code yet. Share it with customers and they'll show up here.",
                  textAlign: TextAlign.center,
                  style: ptstyle(
                    size: 12,
                    weight: 400,
                    color: ch.onSurfaceVariant,
                  ),
                ),
              )
            else
              Container(
                decoration: BoxDecoration(
                  color: ch.surfaceContainerLow,
                  borderRadius: BorderRadius.circular(18),
                ),
                child: Column(
                  children: [
                    for (var i = 0; i < p.promoUsers.length; i++) ...[
                      _PromoUserRow(user: p.promoUsers[i]),
                      if (i < p.promoUsers.length - 1)
                        Divider(
                          height: 1,
                          indent: 60,
                          color: ch.outlineVariant.withOpacity(0.4),
                        ),
                    ],
                  ],
                ),
              ),
          ],
        ),
      ),
    );
  }
}

class _PromoUserRow extends StatelessWidget {
  const _PromoUserRow({required this.user});
  final PromoUser user;

  @override
  Widget build(BuildContext context) {
    final ch = Theme.of(context).colorScheme;
    final initial = user.name.trim().isEmpty ? "?" : user.name.trim()[0];
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      child: Row(
        children: [
          CircleAvatar(
            radius: 17,
            backgroundColor: ch.primary.withOpacity(0.12),
            child: Text(
              initial.toUpperCase(),
              style: ptstyle(size: 13, weight: 700, color: ch.primary),
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              user.name,
              style: ptstyle(size: 13, weight: 600, color: ch.onSurface),
            ),
          ),
          if (user.usedAt != null)
            Text(
              user.usedAt!.toAgo(),
              style: ptstyle(size: 11, weight: 400, color: ch.onSurfaceVariant),
            ),
        ],
      ),
    );
  }
}
